int main() {
    int N;
    scanf("%d", &N);

    int frames[10000];
    int jersey[10000];
    char team[10000][10];
    double x[10000], y[10000];

    for (int i = 0; i < N; i++) {
        scanf("%d %d %s %lf %lf", &frames[i], &jersey[i], team[i], &x[i], &y[i]);
    }

    // For each team A and B, find longest pass
    double bestDistA = -1, bestDistB = -1;
    int bestTimeA = -1, bestTimeB = -1;

    for (int i = 0; i < N-1; i++) {
        if (strcmp(team[i], team[i+1]) == 0 && jersey[i] != jersey[i+1]) {
            // This is a pass
            double dx = x[i+1] - x[i];
            double dy = y[i+1] - y[i];
            double dist = sqrt(dx*dx + dy*dy);
            int time = frames[i+1] - frames[i];

            if (strcmp(team[i], "A") == 0) {
                if (dist > bestDistA || (dist == bestDistA && time < bestTimeA)) {
                    bestDistA = dist;
                    bestTimeA = time;
                }
            } else {
                if (dist > bestDistB || (dist == bestDistB && time < bestTimeB)) {
                    bestDistB = dist;
                    bestTimeB = time;
                }
            }
        }
    }

    if (bestDistA < 0) printf("-1 -1\n");
    else printf("%.2f %d\n", bestDistA, bestTimeA);

    if (bestDistB < 0) printf("-1 -1\n");
    else printf("%.2f %d\n", bestDistB, bestTimeB);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef long long ll;

typedef struct {
    int frame;
    int player;
    char team;
    ll x, y;
} Event;

static int cmpEvent(const void *a, const void *b) {
    const Event *ea = (const Event *)a;
    const Event *eb = (const Event *)b;
    if (ea->frame != eb->frame) return (ea->frame < eb->frame) ? -1 : 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Event *ev = (Event *)malloc(sizeof(Event) * N);
    for (int i = 0; i < N; i++) {
        scanf("%d %d %c %lld %lld", &ev[i].frame, &ev[i].player, &ev[i].team, &ev[i].x, &ev[i].y);
    }

    qsort(ev, N, sizeof(Event), cmpEvent);

    double bestDistA = -1.0, bestDistB = -1.0;
    int bestTimeA = -1, bestTimeB = -1;

    for (int i = 1; i < N; i++) {
        if (ev[i].team == ev[i - 1].team && ev[i].player != ev[i - 1].player) {
            ll dx = ev[i].x - ev[i - 1].x;
            ll dy = ev[i].y - ev[i - 1].y;
            double dist = sqrt((double)dx * (double)dx + (double)dy * (double)dy);
            int dt = ev[i].frame - ev[i - 1].frame;

            if (ev[i].team == 'A') {
                if (dist > bestDistA + 1e-9 || (fabs(dist - bestDistA) <= 1e-9 && (bestTimeA == -1 || dt < bestTimeA))) {
                    bestDistA = dist;
                    bestTimeA = dt;
                }
            } else if (ev[i].team == 'B') {
                if (dist > bestDistB + 1e-9 || (fabs(dist - bestDistB) <= 1e-9 && (bestTimeB == -1 || dt < bestTimeB))) {
                    bestDistB = dist;
                    bestTimeB = dt;
                }
            }
        }
    }

    if (bestDistA < 0) printf("-1 -1\n");
    else printf("%.6f %d\n", bestDistA, bestTimeA);

    if (bestDistB < 0) printf("-1 -1\n");
    else printf("%.6f %d\n", bestDistB, bestTimeB);

    free(ev);
    return 0;
}

