int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<Event> events(N);
    for (int i = 0; i < N; ++i) {
        cin >> events[i].frame >> events[i].player >> events[i].team >> events[i].x >> events[i].y;
    }

    unordered_map<int, pair<double, double>> lastPos; // player -> last (x, y)
    unordered_map<int, int> lastFrame;                // player -> last frame seen

    double bestDistA = -1, bestDistB = -1;
    int bestTimeA = INT_MAX, bestTimeB = INT_MAX;

    for (const auto& e : events) {
        int id = e.player;
        if (lastPos.count(id)) {
            double dx = e.x - lastPos[id].first;
            double dy = e.y - lastPos[id].second;
            double dist = sqrt(dx*dx + dy*dy);
            int timeDiff = e.frame - lastFrame[id];

            if (e.team == "A") {
                if (dist > bestDistA || (abs(dist - bestDistA) < 1e-9 && timeDiff < bestTimeA)) {
                    bestDistA = dist;
                    bestTimeA = timeDiff;
                }
            } else {
                if (dist > bestDistB || (abs(dist - bestDistB) < 1e-9 && timeDiff < bestTimeB)) {
                    bestDistB = dist;
                    bestTimeB = timeDiff;
                }
            }
        }
        lastPos[id] = {e.x, e.y};
        lastFrame[id] = e.frame;
    }

    cout << fixed << setprecision(10);
    if (bestDistA < 0) cout << -1 << " " << -1 << "\n";
    else cout << bestDistA << " " << bestTimeA << "\n";

    if (bestDistB < 0) cout << -1 << " " << -1 << "\n";
    else cout << bestDistB << " " << bestTimeB << "\n";

    return 0;
