using namespace std;

int main() {
    int N;
    cin >> N;

    vector<tuple<long long, int, string, double, double>> rows(N);
    for (int i = 0; i < N; i++) {
        long long frame; int jersey; string team; double x, y;
        cin >> frame >> jersey >> team >> x >> y;
        rows[i] = {frame, jersey, team, x, y};
    }

    // Find passes: consecutive rows where player changes
    // Pass belongs to the team of the passer (first player)

    map<string, pair<double, long long>> best; // team -> (max_dist, min_time for that dist)

    for (int i = 0; i + 1 < N; i++) {
        auto [f1, j1, t1, x1, y1] = rows[i];
        auto [f2, j2, t2, x2, y2] = rows[i+1];

        // A pass occurs if same team but different player? Or any player change?
        // I'll assume: same team, different player = pass
        if (t1 == t2 && j1 != j2) {
            double dist = sqrt((x2-x1)*(x2-x1) + (y2-y1)*(y2-y1));
            long long time = f2 - f1;

            if (best.find(t1) == best.end()) {
                best[t1] = {dist, time};
            } else {
                auto [bd, bt] = best[t1];
                if (dist > bd || (dist == bd && time < bt)) {
                    best[t1] = {dist, time};
                }
            }
        }
    }

    // Output for team A and team B
    for (string team : {"A", "B"}) {
        if (best.find(team) == best.end()) {
            cout << team << ": -1 -1\n";
        } else {
            auto [d, t] = best[team];
            cout << team << ": " << fixed << setprecision(2) << d << " " << t << "\n";
        }
    }

    return 0;
}

#include <bits/stdc++.h>
