struct Event {
    long long frame;
    int jersey;
    char team;
    double x, y;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    vector<Event> a, b;
    a.reserve(N);
    b.reserve(N);

    for (int i = 0; i < N; ++i) {
        Event e;
        cin >> e.frame >> e.jersey >> e.team >> e.x >> e.y;
        if (e.team == 'A') a.push_back(e);
        else b.push_back(e);
    }

    auto solve = [](const vector<Event>& v) {
        double bestDist = -1.0;
        long long bestTime = -1;

        for (int i = 1; i < (int)v.size(); ++i) {
            if (v[i - 1].jersey != v[i].jersey) {
                double dx = v[i].x - v[i - 1].x;
                double dy = v[i].y - v[i - 1].y;
                double dist = sqrt(dx * dx + dy * dy);
                long long t = v[i].frame - v[i - 1].frame;

                if (dist > bestDist + 1e-12) {
                    bestDist = dist;
                    bestTime = t;
                } else if (fabs(dist - bestDist) <= 1e-12 && t < bestTime) {
                    bestTime = t;
                }
            }
        }

        if (bestDist < 0) {
            cout << -1 << " " << -1 << "\n";
        } else {
            cout << fixed << setprecision(6) << bestDist << " " << bestTime << "\n";
        }
    };

    solve(a);
    solve(b);

    return 0;
}

