public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());

        // Skip header line if present, but problem statement doesn't mention it,
        // so we assume N lines follow directly with: frame, jersey, team, x, y
        double maxDistA = -1, maxDistB = -1;
        int timeA = -1, timeB = -1;

        // Store previous event for each team
        int prevFrameA = -1, prevJerseyA = -1;
        double prevXA = 0, prevYA = 0;
        boolean hasPrevA = false;

        int prevFrameB = -1, prevJerseyB = -1;
        double prevXB = 0, prevYB = 0;
        boolean hasPrevB = false;

        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            int frame = Integer.parseInt(parts[0]);
            int jersey = Integer.parseInt(parts[1]);
            char team = parts[2].charAt(0);
            double x = Double.parseDouble(parts[3]);
            double y = Double.parseDouble(parts[4]);

            if (team == 'A') {
                if (hasPrevA && prevJerseyA != jersey) {
                    double dist = Math.sqrt((x - prevXA) * (x - prevXA) + (y - prevYA) * (y - prevYA));
                    int timeDiff = frame - prevFrameA;
                    if (dist > maxDistA || (Math.abs(dist - maxDistA) < 1e-9 && timeDiff < timeA)) {
                        maxDistA = dist;
                        timeA = timeDiff;
                    }
                }
                prevFrameA = frame;
                prevJerseyA = jersey;
                prevXA = x;
                prevYA = y;
                hasPrevA = true;
            } else { // team B
                if (hasPrevB && prevJerseyB != jersey) {
                    double dist = Math.sqrt((x - prevXB) * (x - prevXB) + (y - prevYB) * (y - prevYB));
                    int timeDiff = frame - prevFrameB;
                    if (dist > maxDistB || (Math.abs(dist - maxDistB) < 1e-9 && timeDiff < timeB)) {
                        maxDistB = dist;
                        timeB = timeDiff;
                    }
                }
                prevFrameB = frame;
                prevJerseyB = jersey;
                prevXB = x;
                prevYB = y;
                hasPrevB = true;
            }
        }

        // Format output
        if (maxDistA < 0) {
            System.out.println("-1 -1");
        } else {
            System.out.printf("%.6f %d%n", maxDistA, timeA);
        }
        if (maxDistB < 0) {
            System.out.println("-1 -1");
        } else {
            System.out.printf("%.6f %d%n", maxDistB, timeB);
        }
    }
}

