import java.io.*;
import java.util.*;

/*
Assumed interpretation of the statement from the provided description:

Each row describes one moment when a player has the ball:
frameNumber playerNumber team x y

A pass for a team is formed by two consecutive rows in time where:
- both rows belong to the same team
- the player number changes (ball moved from one player to another)

For such a pass:
- distance = Euclidean distance between the coordinates in the two rows
- time = difference in frame numbers

For each team, output the longest pass distance and its time.
If multiple passes have the same longest distance, choose the one with the shortest time.
If a team made no pass, output: -1 -1

Because the exact original output format was not fully available, this solution prints:
A_distance A_time
B_distance B_time

Distances are printed with 6 digits after decimal point.

If the actual judge uses team labels other than A/B, this code still works by collecting teams
in encounter order and printing results for team "A" then team "B" if present; otherwise the first
two distinct team labels encountered.
*/
public class Main {
    static class Event {
        long frame;
        String player;
        String team;
        double x, y;

        Event(long frame, String player, String team, double x, double y) {
            this.frame = frame;
            this.player = player;
            this.team = team;
            this.x = x;
            this.y = y;
        }
    }

    static class BestPass {
        boolean exists = false;
        double dist = -1;
        long time = -1;

        void consider(double d, long t) {
            if (!exists || d > dist + 1e-9 || (Math.abs(d - dist) <= 1e-9 && t < time)) {
                exists = true;
                dist = d;
                time = t;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        Integer nObj = fs.nextIntNullable();
        if (nObj == null) return;
        int N = nObj;

        List<Event> events = new ArrayList<>();
        LinkedHashSet<String> teamsSeen = new LinkedHashSet<>();

        for (int i = 0; i < N; i++) {
            long frame = fs.nextLong();
            String player = fs.next();
            String team = fs.next();
            double x = fs.nextDouble();
            double y = fs.nextDouble();
            events.add(new Event(frame, player, team, x, y));
            teamsSeen.add(team);
        }

        events.sort(Comparator.comparingLong(e -> e.frame));

        Map<String, BestPass> best = new HashMap<>();
        for (String team : teamsSeen) best.put(team, new BestPass());

        for (int i = 1; i < events.size(); i++) {
            Event prev = events.get(i - 1);
            Event cur = events.get(i);

            if (prev.team.equals(cur.team) && !prev.player.equals(cur.player)) {
                double dx = cur.x - prev.x;
                double dy = cur.y - prev.y;
                double dist = Math.hypot(dx, dy);
                long time = cur.frame - prev.frame;
                best.computeIfAbsent(cur.team, k -> new BestPass()).consider(dist, time);
            }
        }

        String team1 = null, team2 = null;
        if (teamsSeen.contains("A")) team1 = "A";
        if (teamsSeen.contains("B")) team2 = "B";

        if (team1 == null || team2 == null) {
            Iterator<String> it = teamsSeen.iterator();
            if (team1 == null && it.hasNext()) team1 = it.next();
            if (team2 == null) {
                while (it.hasNext()) {
                    String s = it.next();
                    if (!s.equals(team1)) {
                        team2 = s;
                        break;
                    }
                }
            }
        }

        StringBuilder out = new StringBuilder();
        printTeam(out, best.get(team1));
        out.append('\n');
        printTeam(out, best.get(team2));
        System.out.print(out.toString());
    }

    static void printTeam(StringBuilder out, BestPass bp) {
        if (bp == null || !bp.exists) {
            out.append("-1 -1");
        } else {
            out.append(String.format(Locale.US, "%.6f %d", bp.dist, bp.time));
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            StringBuilder sb = new StringBuilder();
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        Integer nextIntNullable() throws IOException {
            String s = next();
            return s == null ? null : Integer.parseInt(s);
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}
